 'fee_rule','standard','fee_bps',pl.repeat_fee_bps,'fee_floor_vnd',pl.fee_floor_vnd,'fee_cap_vnd',pl.fee_cap_vnd,'fee_vnd',CASE WHEN pl.repeat_fee_bps=0 THEN 0 ELSE least(pl.fee_cap_vnd,greatest(pl.fee_floor_vnd,ref.div_round(23000000::numeric*pl.repeat_fee_bps,10000))) END,
 'seller_bank_account_id',b.id,'seller_bank_code',b.bank_code,'seller_account_masked',b.account_masked,'seller_account_holder',b.holder_name,
