CREATE FUNCTION test.reduction_instruction(p_patch jsonb) RETURNS void LANGUAGE sql AS $$
 INSERT INTO core.bank_instructions SELECT (jsonb_populate_record(NULL::core.bank_instructions,to_jsonb(b)||jsonb_build_object('id',gen_random_uuid(),'code','TEST-RED-'||gen_random_uuid())||p_patch)).* FROM core.bank_instructions b WHERE basis_kind='deposit_adjustment' AND basis_id=current_setting('test.cmd.adjustment')::uuid LIMIT 1
$$;
SELECT test.expect_error('M10 không hoàn thêm vượt delta đã giữ', $$SELECT test.reduction_instruction('{"amount_vnd":1}')$$,'ck_instruction_deposit_adjustment');
SELECT test.expect_error('M10 sai căn cứ phụ lục bị chặn', $$SELECT test.reduction_instruction(jsonb_build_object('basis_id',gen_random_uuid()))$$,'ck_instruction_deposit_adjustment');
SELECT test.expect_error('M10 không nhân quyền hoàn bằng adjustment thứ hai', $$INSERT INTO core.deposit_adjustments(deposit_id,order_version_no,delta_deposit_vnd) VALUES(test.id('LS3:deposit'),2,-3450000)$$,'23505');
